import 'dart:convert';
import 'dart:typed_data';

import 'package:flutter/material.dart';

/// NUCLEI TECH logo supplied for the application.
/// Stored inline so the same brand asset works on Android, iOS, Web and Windows
/// without relying on a remote image URL.
class BrandLogo extends StatelessWidget {
  const BrandLogo({
    super.key,
    this.width,
    this.height,
    this.fit = BoxFit.contain,
  });

  final double? width;
  final double? height;
  final BoxFit fit;

  static final Uint8List _bytes = base64Decode(_logoBase64);

  @override
  Widget build(BuildContext context) {
    return Image.memory(
      _bytes,
      width: width,
      height: height,
      fit: fit,
      filterQuality: FilterQuality.high,
      gaplessPlayback: true,
      semanticLabel: 'NUCLEI TECH',
    );
  }
}

const String _logoBase64 =
    '';
